async function hotMore(){if(HLD||HOT.length>=150)return;HLD=true;if(!HOT.length)paint();try{if(!HPOOL.length){HPOOL=await hotBatch();if(!HPOOL.length)HDEAD=true}HOT=[...HOT,...HPOOL.splice(0,20)].slice(0,150);hotSave()}catch(e){HDEAD=true}finally{HLD=false}if(V=='home'&&T=='ht')paint()}
