async function runSearch(){const raw=SQV.trim();if(raw.length<2)return;SQD=true;SQT='u';const [u,p]=await Promise.all([sb.rpc('search_profiles',{q:raw,lim:20}),sb.from('feed').select('*').is('repost_of',null).ilike('body','%'+raw.replace(/[%,()*\\_]/g,' ').trim()+'%').order('created_at',{ascending:false}).limit(20)]);SR=(u.data||[]).filter(x=>!BLOCKS.has(x.id));SP=(p.data||[]).filter(x=>!BLOCKS.has(x.user_id)&&!(x.repost_of&&!x.o_handle));POSTS=SP;LK=new Set();BM=new Set();RP=new Set();await marks([...new Set(SP.map(tid))]);trackViews(SP);if(V=='search'&&$('#sr'))$('#sr').innerHTML=srHtml()}
