function legalV(kind){
  const tabs=`<div class="tabs"><button class="${kind=='privacy'?'on':''}" data-a="legal" data-id="privacy">Privacy</button><button class="${kind=='terms'?'on':''}" data-a="legal" data-id="terms">Terms</button><button class="${kind=='retention'?'on':''}" data-a="legal" data-id="retention">Retention</button></div>`;
  const mail=`<a class="lnk" href="mailto:${LEGAL_EMAIL}">${LEGAL_EMAIL}</a>`;
  if(kind=='privacy'){
    return`${tabs}<div class="pg legpg"><h2>NYXORA Privacy Policy</h2><p class="sm mu">Effective November 2026 · Contact: ${mail}</p>
    <div class="legcard"><b>1. Information We Collect</b><p class="sm mu">When you register and use NYXORA, we store your email address, display name, @handle, optional profile details (bio, location, website link, interests, avatar, banner), posts, comments, likes, bookmarks, follows, direct messages, streak history, and any safety preferences (hidden keywords, muted accounts, blocked accounts, or reports) you create.</p></div>
    <div class="legcard"><b>2. How Your Data Is Used</b><p class="sm mu">Your data powers feeds, Discover People matching, 1-on-1 messaging, 7-day UTC activity streaks, and abuse moderation. NYXORA does not sell your personal information and never exposes private direct messages or private reports to the public feed.</p></div>
    <div class="legcard"><b>3. Automatic Data Expiry Rules</b><p class="sm mu">• <b>Notifications (90 Days):</b> Ordinary social notifications expire and are permanently deleted 90 days after delivery. Moderation action notices remain retained for account safety records.<br>• <b>Direct Messages (7 Days):</b> Private messages automatically expire and are permanently deleted 7 days after they were sent. Deletion on NYXORA cannot erase screenshots or copies saved outside the app by a recipient.<br>• <b>Post Images (30 Days):</b> Post image attachments automatically expire 30 days after upload and are removed from feeds and storage. Profile avatars and banners stay active until replaced or deleted.</p></div>
    <div class="legcard"><b>4. Downloads, Moderation &amp; Safety</b><p class="sm mu">Post authors can toggle download buttons on or off per image, though screenshots cannot always be prevented. Private reports are visible only to the reporter and authorized NYXORA moderators.</p></div>
    <div class="legcard"><b>5. Your Rights &amp; Contact</b><p class="sm mu">You may update your profile, change your username, download your active photos, block or mute accounts, or disable first-contact DMs at any time. For privacy questions or account/data removal requests, email ${mail}.</p></div></div>`;
  }
  if(kind=='terms'){
    return`${tabs}<div class="pg legpg"><h2>NYXORA Terms of Service</h2><p class="sm mu">Effective November 2026 · Contact: ${mail}</p>
    <div class="legcard"><b>1. Account &amp; Eligibility</b><p class="sm mu">You are responsible for safeguarding your login credentials and all activity under your account. Choose an accurate display name and follow NYXORA handle rules (3–20 lowercase letters, numbers, or underscores).</p></div>
    <div class="legcard"><b>2. Acceptable Conduct</b><p class="sm mu">Do not post harassment, threats, hate speech, non-consensual explicit material, scams, impersonation, or unlawful content. Do not attempt to bypass daily quotas, rate limits (8 direct messages per 30 seconds), block restrictions, or backend security controls.</p></div>
    <div class="legcard"><b>3. Content &amp; Fair Moderation</b><p class="sm mu">You retain ownership of the content you publish while granting NYXORA permission to host and display it within the service. Reports are reviewed privately by human moderators before removal; when content violates these rules and is removed, NYXORA sends an accurate removal reason notice to the owner rather than issuing unreviewed blind bans.</p></div>
    <div class="legcard"><b>4. Free &amp; Elite Accounts</b><p class="sm mu">Free accounts include 10 posts/day (1,500 chars), 10 post images/day, 300 DMs/day, and Midnight theme. Elite accounts include 50 posts/day (3,000 chars), post editing, 20 post images/day, 700 DMs/day, 6 custom themes, and visual badges. Elite marks (blue tick, diamond, golden glow) denote membership perks and <b>do not verify real-world identity</b> unless separate verification is explicitly performed.</p></div>
    <div class="legcard"><b>5. Service Availability &amp; Contact</b><p class="sm mu">NYXORA is provided on an as-available basis and scheduled automated expiry jobs permanently purge 7-day messages, 30-day post images, and 90-day notifications. Questions or moderation appeals can be sent to ${mail}.</p></div></div>`;
  }
  return`${tabs}<div class="pg legpg"><h2>Data Retention &amp; Safety Guide</h2><p class="sm mu">How automatic expiry, privacy controls, and moderation work across NYXORA.</p>
  <div class="legcard"><b>90-Day Notification Expiry</b><p class="sm mu">Ordinary notifications (follows, likes, replies, reposts, quotes) remain visible for 90 days and are automatically cleaned up afterward. Report confirmation and moderation notices are preserved so both reporters and owners keep a clear record.</p></div>
  <div class="legcard"><b>7-Day Direct Message Deletion</b><p class="sm mu">Messages in 1-on-1 chats automatically expire 7 days after sending. You can edit a sent message within 1 hour of sending (before expiry). Global limits are enforced server-side: max 8 messages per 30 seconds, plus 300/day (Free) or 700/day (Elite) resetting at 00:00 UTC. Blocking a participant immediately blocks reading and sending in that thread.</p></div>
  <div class="legcard"><b>30-Day Post Image Expiry &amp; Downloads</b><p class="sm mu">Post photos are compressed under 300 KB and automatically expire 30 days after publish (avatars and banners do not expire after 30 days). Authors can turn off download buttons per post, though screenshots or external saves cannot always be prevented.</p></div>
  <div class="legcard"><b>Reporting &amp; Admin Review</b><p class="sm mu">You can privately report posts, comments, messages, or profiles. Submitting a report sends you a confirmation notice and places it in a restricted admin-only review queue. Moderators can dismiss a report, remove violating content with an accurate reason delivered to the owner, or send a caution notice.</p></div>
  <div class="legcard"><b>Support &amp; Appeals</b><p class="sm mu">Need help with privacy, safety, or a moderation notice? Reach us anytime at ${mail}.</p></div></div>`;
}
